import{_ as a,o as s,c as r,a2 as t}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"苏珊·雅克","description":"","frontmatter":{"title":"苏珊·雅克","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/苏珊·雅克.md","filePath":"04_people/苏珊·雅克.md"}'),l={name:"04_people/苏珊·雅克.md"};function i(o,e,h,n,_,m){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="苏珊·雅克-susan-jacques" tabindex="-1">苏珊·雅克（Susan Jacques） <a class="header-anchor" href="#苏珊·雅克-susan-jacques" aria-label="Permalink to &quot;苏珊·雅克（Susan Jacques）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：Borsheim&#39;s（波诗明&#39;s）珠宝店CEO</li><li><strong>与巴菲特关系</strong>：Borsheim&#39;s是被伯克希尔收购的珠宝零售巨头，雅克是伯克希尔旗下珠宝业务的掌门人</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>苏珊·雅克是Borsheim&#39;s珠宝店的长期领导者。Borsheim&#39;s创建于1947年，总部位于内布拉斯加州奥马哈，是美国最大、最著名的珠宝零售店之一。该店由艾克·弗里德曼（Ike Friedman）家族创立，以其丰富的钻石收藏和卓越的客户服务闻名于世。巴菲特与Borsheim&#39;s渊源深厚，早在1965年巴菲特就开始关注这家公司。1993年，巴菲特通过伯克希尔·哈撒韦收购了Borsheim&#39;s的多数股权，并邀请苏珊·雅克担任CEO。在雅克的领导下，Borsheim&#39;s将传统的珠宝零售艺术与现代商业管理完美结合，创造出卓越的客户体验。Borsheim&#39;s以&quot;无压力销售&quot;模式著称，销售人员不收佣金、不进行硬性推销，让顾客在轻松环境中选购珠宝，这一独特文化成为行业标杆。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1947年</strong>：Borsheim&#39;s由弗里德曼家族在奥马哈创立</li><li><strong>1993年</strong>：伯克希尔收购Borsheim&#39;s多数股权，苏珊·雅克被任命为CEO</li><li><strong>1993年后</strong>：在雅克带领下，Borsheim&#39;s业绩持续增长，成为伯克希尔旗下盈利能力最强的零售业务之一</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=苏珊·雅克在1997年股东信中的原话">1997年：完整翻译|/01_letters/1997年/翻译</a></li><li><a href="/search.html?q=苏珊·雅克在2010年股东信中的原话">2010年：完整翻译|/01_letters/2010年/翻译</a></li><li><a href="/search.html?q=苏珊·雅克在1993年股东信中的原话">1993年：完整翻译|/01_letters/1993年/翻译</a></li><li><a href="/search.html?q=苏珊·雅克在1998年股东信中的原话">1998年：完整翻译|/01_letters/1998年/翻译</a></li><li><a href="/search.html?q=苏珊·雅克在2009年股东信中的原话">2009年：完整翻译|/01_letters/2009年/翻译</a></li></ul>',11)])])}const d=a(l,[["render",i]]);export{u as __pageData,d as default};
